int Length(int s[],int i){
    int seq[20],t,j,k,b,m,c;
    int count=0;

    for(j=0;j<i;j++){
        count=0;

        for(b=1;b<i&&b>j;b++){

            c=0;
            for(m=1;m<b-j+1;m++){
                if (s[b]>s[b-m]) c=c+1;
            }

            if(s[j]<s[b]&&c == b-j) count = count +1;
            else continue;

        }
        seq[j]=count+1;

    }

    int a; int num = 0;
    for(t=0;t<i;t++){
        num=0;
        for(k=0;k<i;k++){
            if(seq[t]>=seq[k]) num = num+1;
        }
        if (num==i) a = seq[t];


    }
    return a;
}











